internal data class TourCopy(val uk: String, val en: String, val sk: String) {
    fun text(language: AppLanguage = TaktI18n.language) = when (language) {
        AppLanguage.ENGLISH -> en
        AppLanguage.SLOVAK -> sk
        else -> uk
    }
}

